using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;
using ModelContextProtocol.Server;

[McpServerToolType]
public sealed class WeatherTools
{
    private readonly IHttpClientFactory _httpClientFactory;

    public WeatherTools(IHttpClientFactory httpClientFactory)
    {
        _httpClientFactory = httpClientFactory;
    }

    [McpServerTool, Description("Get the current temperature for a location.")]
    public async Task<string> GetCurrentWeather(
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude)
    {
        var client = _httpClientFactory.CreateClient("WeatherApi");
        var response = await client.GetFromJsonAsync<WeatherResponse>(
            $"v1/forecast?latitude={latitude}&longitude={longitude}&current_weather=true");

        if (response?.CurrentWeather is null)
            return "Unable to retrieve weather data.";

        var w = response.CurrentWeather;
        return $"Temperature: {w.Temperature}°C, Wind: {w.WindSpeed} km/h, Direction: {w.WindDirection}°";
    }

    [McpServerTool, Description("Look up coordinates for a city name.")]
    public async Task<string> GeocodeCityName(
        [Description("City name to search for")] string cityName)
    {
        var client = _httpClientFactory.CreateClient("WeatherApi");
        var url = $"https://geocoding-api.open-meteo.com/v1/search?name={Uri.EscapeDataString(cityName)}&count=1";
        var response = await client.GetFromJsonAsync<GeocodeResponse>(url);

        if (response?.Results is not { Count: > 0 })
            return $"No results found for '{cityName}'.";

        var r = response.Results[0];
        return $"{r.Name} ({r.Country}): lat={r.Latitude}, lon={r.Longitude}";
    }
}

// DTOs for Open-Meteo API responses

public sealed class WeatherResponse
{
    [JsonPropertyName("current_weather")]
    public CurrentWeather? CurrentWeather { get; set; }
}

public sealed class CurrentWeather
{
    [JsonPropertyName("temperature")]
    public double Temperature { get; set; }

    [JsonPropertyName("windspeed")]
    public double WindSpeed { get; set; }

    [JsonPropertyName("winddirection")]
    public double WindDirection { get; set; }
}

public sealed class GeocodeResponse
{
    [JsonPropertyName("results")]
    public List<GeocodeResult>? Results { get; set; }
}

public sealed class GeocodeResult
{
    [JsonPropertyName("name")]
    public string Name { get; set; } = "";

    [JsonPropertyName("country")]
    public string Country { get; set; } = "";

    [JsonPropertyName("latitude")]
    public double Latitude { get; set; }

    [JsonPropertyName("longitude")]
    public double Longitude { get; set; }
}

